            period: p,
            collection_status: i === 3 ? r() < 0.72 ? 'Collected' : 'Outstanding' : 'Collected',
            billable_aum: aum,
            fee_rate: a.fee_rate,
            fee_amount: dmRound(aum * a.fee_rate / 100 / 4, 0),
