const DM_GROUPS = [{
  label: 'Data sources',
  ids: ['client_book', 'holdings', 'raw_accounts', 'performance', 'account_history', 'return_stats', 'period_summary', 'target_allocation', 'money_movement', 'billing', 'raw_securities']
}];
function dmDataset(id) {
  const d = DM_DATASETS[id] || DM_DATASETS.client_book;
  if (d.rowsFrom) return {
    ...d,
    fields: DM_DATASETS[d.rowsFrom].fields,
    rows: DM_DATASETS[d.rowsFrom].rows
  };
  return d;
}
function dmFields(id) {
  return dmDataset(id).fields;
}
function dmField(id, k) {
  return dmFields(id).find(f => f.k === k);
}
const _dmRowCache = {};
function dmRows(id) {
  if (dmDataset(id).needsConnect) return [];
  if (id === 'alerts' && window.fieldInsights) return dmDataset(id).rows();
  if (!_dmRowCache[id]) _dmRowCache[id] = dmDataset(id).rows();
  return _dmRowCache[id];
}

/* ---- relationships between datasets --------------------------------------
   Every dataset is a view of the same book, so they share identity columns. A
   value can therefore be pulled from another dataset without leaving the one
   you are working in: we join on the most specific column the two share, then
   aggregate the related rows that belong to each group.

   A cross-dataset reference is written "dataset.field", e.g. "performance.return_pct". */
const DM_JOIN_KEYS = ['account', 'client', 'household', 'ticker', 'security', 'advisor', 'segment', 'model_portfolio', 'account_type', 'custodian', 'asset_class', 'state'];
function dmJoinKey(aId, bId) {
  if (aId === bId) return null;
  const A = new Set(dmFields(aId).map(f => f.k));
  const B = new Set(dmFields(bId).map(f => f.k));
  return DM_JOIN_KEYS.find(k => A.has(k) && B.has(k)) || null;
}

/* datasets reachable from this one, with the column they join on */
const DM_SOURCE_IDS = DM_GROUPS.flatMap(g => g.ids);
function dmRelated(id) {
  return DM_SOURCE_IDS.filter(x => x !== id && !DM_DATASETS[x].gate && dmJoinKey(id, x)).map(x => ({
    id: x,
    label: DM_DATASETS[x].label,
    icon: DM_DATASETS[x].icon,
    key: dmJoinKey(id, x)
  }));
}

/* "performance.return_pct" -> { ds, k }; a plain key returns null */
function dmParseRef(k) {
  const i = String(k).indexOf('.');
  if (i < 0) return null;
  const ds = k.slice(0, i),
    field = k.slice(i + 1);
  return DM_DATASETS[ds] && dmFields(ds).some(f => f.k === field) ? {
    ds,
    k: field
  } : null;
}

/* a field descriptor for any key, local or cross-dataset */
function dmFieldRef(baseId, k) {
  const ref = dmParseRef(k);
  if (!ref) return dmField(baseId, k);
  const f = dmField(ref.ds, ref.k);
  if (!f) return null;
  return {
    ...f,
    k,
    label: f.label,
    refLabel: f.label + ' \u00b7 ' + DM_DATASETS[ref.ds].label,
    ref
  };
}

/* rows of a dataset indexed by a join column, built once per pair */
const _dmIndex = {};
function dmIndexBy(dsId, key) {
  const ck = dsId + '|' + key;
  if (!_dmIndex[ck]) {
    const m = new Map();
    dmRows(dsId).forEach(r => {
      const v = r[key];
      if (v == null || v === '') return;
      let a = m.get(v);
      if (!a) {
        a = [];
        m.set(v, a);
      }
      a.push(r);
    });
    _dmIndex[ck] = m;
  }
  return _dmIndex[ck];
}

/* ---- aggregation -------------------------------------------------------- */
const DM_AGGS = [{
  id: 'sum',
  label: 'Sum'
}, {
  id: 'avg',
  label: 'Average'
}, {
  id: 'min',
  label: 'Min'
}, {
  id: 'max',
  label: 'Max'
}, {
  id: 'count',
  label: 'Count'
}, {
  id: 'countd',
  label: 'Count distinct'
}, {
  id: 'median',
  label: 'Median'
}];
function dmAgg(agg, vals) {
  const nums = vals.filter(v => v != null && v !== '' && !isNaN(Number(v))).map(Number);
  switch (agg) {
    case 'count':
      return vals.length;
    case 'countd':
      return new Set(vals).size;
    case 'avg':
      return nums.length ? nums.reduce((a, b) => a + b, 0) / nums.length : 0;
    case 'min':
      return nums.length ? Math.min(...nums) : 0;
    case 'max':
      return nums.length ? Math.max(...nums) : 0;
    case 'median':
      {
        if (!nums.length) return 0;
        const s = [...nums].sort((a, b) => a - b),
          m = Math.floor(s.length / 2);
        return s.length % 2 ? s[m] : (s[m - 1] + s[m]) / 2;
      }
    default:
      return nums.reduce((a, b) => a + b, 0);
  }
}

/* ---- formatting --------------------------------------------------------- */
function dmFmt(v, fmt, opts) {
  const o = opts || {};
  if (v == null || v === '') return '\u2014';
  if (typeof fmt === 'string' && fmt.indexOf(':') > 0) {
    const p = fmt.split(':');
    fmt = p[0];
    if (o.decimals == null) o.decimals = Number(p[1]);
  }
  if (o.decimals != null && !isNaN(o.decimals) && (fmt === 'usd' || fmt === 'pct' || fmt === 'num')) {
    const n = Number(v),
      d = o.decimals;
    const body = Math.abs(n).toLocaleString(undefined, {
      minimumFractionDigits: d,
      maximumFractionDigits: d
    });
    const sign = n < 0 ? '-' : '';
    if (fmt === 'usd') return sign + '$' + body;
    if (fmt === 'pct') return sign + body + '%';
    return sign + body;
  }
  if (fmt === 'usd') {
    const n = Number(v),
      a = Math.abs(n),
      sign = n < 0 ? '-' : '';
    if (o.compact !== false && a >= 1000000) return sign + '$' + (a / 1000000).toFixed(a >= 10000000 ? 1 : 2) + 'M';
    if (o.compact !== false && a >= 10000) return sign + '$' + Math.round(a / 1000) + 'K';
    return sign + '$' + a.toLocaleString(undefined, {
      maximumFractionDigits: 0
    });
  }
  if (fmt === 'pct') return dmRound(Number(v), 2) + '%';
  if (fmt === 'num') {
    const n = Number(v);
    return Number.isInteger(n) ? n.toLocaleString() : n.toLocaleString(undefined, {
      maximumFractionDigits: 2
    });
  }
  return String(v);
}
function dmFmtFull(v, fmt) {
  if (typeof fmt === 'string' && fmt.indexOf(':') > 0) return dmFmt(v, fmt);
  if (fmt === 'usd') return (Number(v) < 0 ? '-' : '') + '$' + Math.abs(Number(v)).toLocaleString(undefined, {
    maximumFractionDigits: 0
  });
  return dmFmt(v, fmt, {
    compact: false
  });
}

