/* Holdings detail — built from the same seeded positions as the tile, so the
   drill-down never disagrees with the summary it opened from. */
TILE_DETAIL_CONFIG.cd_holdings = (() => {
  const pos = dmRows('holdings').filter(p => p.household === 'Young Household');
  const total = pos.reduce((s, p) => s + p.market_value, 0);
  const by = {};
  pos.forEach(p => {
    if (!by[p.ticker]) by[p.ticker] = {
      ticker: p.ticker,
      security: p.security,
      asset: p.asset_class,
      sector: p.sector,
      mv: 0,
      cb: 0,
      accts: new Set()
    };
    const r = by[p.ticker];
    r.mv += p.market_value;
    r.cb += p.cost_basis;
    r.accts.add(p.account);
  });
  const rolled = Object.values(by).sort((x, y) => y.mv - x.mv);
  const byClass = {};
  pos.forEach(p => {
    byClass[p.asset_class] = (byClass[p.asset_class] || 0) + p.market_value;
  });
  const classes = Object.entries(byClass).sort((x, y) => y[1] - x[1]);
  const top = rolled[0] || {
    ticker: '\u2014',
    mv: 0
  };
  const usd = v => '$' + Math.round(v).toLocaleString();
  const usdSigned = v => (v < 0 ? '-' : '+') + '$' + Math.abs(Math.round(v)).toLocaleString();
  return {
    kicker: 'David Young \u00b7 Detail',
    title: 'Holdings',
    subtitle: 'Positions rolled up by security across every account in the household',
    sources: ['schwab', 'fidelity', 'internal'],
    syncedAt: '8 min ago',
    chartTitle: 'Value by asset class',
    noRange: true,
    tableTitle: 'Positions by security',
    kpis: [{
      label: 'Securities',
      value: String(rolled.length),
      delta: pos.length + ' positions',
      tone: 'flat'
    }, {
      label: 'Market Value',
      value: usd(total)
    }, {
      label: 'Largest Holding',
      value: top.ticker,
      delta: (total ? (top.mv / total * 100).toFixed(1) : '0') + ' % of book',
      tone: 'flat'
    }],
    chartOpts: {
      chart: {
        type: 'bar',
        height: 320,
        marginRight: 24
      },
      xAxis: {
        categories: classes.map(c => c[0])
      },
      yAxis: {
        title: {
          text: null
        },
        labels: {
          formatter: function () {
            return dmFmt(this.value, 'usd');
          }
        }
      },
      legend: {
        enabled: false
      },
      tooltip: {
        formatter: function () {
          return '<b>' + this.x + '</b><br/>' + usd(this.y);
        }
      },
      plotOptions: {
        bar: {
          borderRadius: 3,
          pointPadding: 0.08,
          groupPadding: 0.14
        }
      },
      series: [{
        type: 'bar',
        name: 'Market Value',
        color: _GREEN,
        data: classes.map(c => Math.round(c[1]))
      }]
    },
    cols: [{
      key: 'ticker',
      label: 'Ticker'
    }, {
      key: 'security',
      label: 'Security'
    }, {
      key: 'asset',
      label: 'Asset Class',
      muted: true
    }, {
      key: 'sector',
      label: 'Sector',
      muted: true
    }, {
      key: 'accts',
      label: 'Accounts',
      align: 'right',
      muted: true
    }, {
      key: 'value',
      label: 'Market Value',
      align: 'right',
      num: true,
      bold: true
    }, {
      key: 'weight',
      label: 'Weight',
      align: 'right',
      num: true
    }, {
      key: 'unreal',
      label: 'Unrealized',
      align: 'right',
      num: true
    }],
    rows: rolled.map(r => ({
      ticker: r.ticker,
      security: r.security,
      asset: r.asset,
      sector: r.sector,
      accts: String(r.accts.size),
      value: usd(r.mv),
      weight: (total ? (r.mv / total * 100).toFixed(1) : '0') + '%',
      unreal: usdSigned(r.mv - r.cb)
    }))
  };
})();
